#include <iostream>
using namespace std;

int find_index(const int a[], int n, int target) {
    for (int i = 0; i < n; i++) {
        if (a[i] == target) {
            return i;
        }
    }
    return -1;
}

int main() {
    int a[5] = {5, 1, 9, 3, 7};
    cout << find_index(a, 5, 3) << endl;
    cout << find_index(a, 5, 4) << endl;
    return 0;
}

#include <iostream>
using namespace std;

int binary_search_index(const int a[], int n, int target) {
    int low = 0, high = n - 1;
    while (low <= high) {
        int mid = (low + high) / 2;
        if (a[mid] == target) {
            return mid;
        } else if (a[mid] < target) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return -1;
}

int main() {
    int a[7] = {1, 3, 5, 7, 9, 11, 13};
    cout << binary_search_index(a, 7, 5) << endl;
    return 0;
}

